update cellar.makers set website = coalesce(website, 'https://www.klukewhiskeycompany.com'), country = coalesce(country, 'US') where id = 'fc7ce07b-a4cb-4704-bbec-d07b82ecb69c';
select cellar.merge_product('c5ffb0f2-6c45-43e7-b52e-5ed9a3f3fe0a'::uuid, '737834b5-335c-450e-ad78-e89536f15d86'::uuid, null);  -- Blended Bourbon (BB 'Blended Straight Bourbon, Batch 5', 100 proof) -> Small Batch 100 Proof (same line, another batch)
